/**
 * billableCatalog.js — STARTER billable master-data catalogue (India-ready).
 *
 * IMPORTANT:
 * - This is a configurable STARTER catalogue, not an exhaustive list of "all Indian standard tests".
 *   Every tenant is expected to add/remove/edit entries, prices, GST rates, TATs and reference ranges.
 * - Prices are indicative Indian-market starter values in INR and MUST be reviewed per facility.
 * - GST: healthcare services are shown as 0% (as commonly exempt); goods use 12%/18% as commonly
 *   applied — verify current GST law/notifications with your tax advisor before billing.
 * - hsnSac '999316' is the SAC commonly used for medical laboratory services — verify per CA advice.
 * - IVD kits: manufacturer and regulatoryClass are intentionally blank — populate per your procured
 *   brand and its CDSCO (Medical Devices Rules) risk class/registration details.
 * - Reference ranges are adult indicative defaults; labs must validate/replace with method- and
 *   population-specific ranges.
 *
 * CommonJS module. Do not import server code here — pure data only.
 */

'use strict';

// Helper: laboratory test entry (keeps every entry the same shape as the documented schema).
const L = (code, name, subcategory, specimen, container, unit, tatHours, resultType, price, refDefault, method) => ({
  code,
  name,
  category: 'Laboratory Services',
  subcategory,
  specimen,
  container,
  unit,
  tatHours,
  method: method || '',
  refRange: { default: refDefault || '', notes: '' },
  resultType,
  price,
  gst: 0,
  hsnSac: '999316',
});

// Helper: consumable entry.
const C = (code, name, category, unit, packSize, price, gst, expiryTracked) => ({
  code,
  name,
  category,
  unit,
  packSize,
  price,
  gst,
  inventoryTracked: true,
  batchTracked: true,
  expiryTracked: expiryTracked !== false,
});

